{
  "controller": {
    "states": [
      {
        "name": "displayPhaseMs",
        "type": "f64",
        "initial": 0.0
      },
      {
        "name": "previousVibration",
        "type": "bool",
        "initial": false
      },
      {
        "name": "faultEntry",
        "type": "bool",
        "initial": false
      }
    ],
    "calculations": [
      {
        "name": "currentAmperes",
        "type": "f64",
        "expression": "io_0 * 10.0 / 1023.0"
      },
      {
        "name": "temperatureCelsius",
        "type": "f64",
        "expression": "io_1 * 500.0 / 1023.0"
      },
      {
        "name": "motorStatus",
        "type": "i32",
        "expression": {
          "if": "io_2",
          "then": 3,
          "else": {
            "if": {
              ">": [
                "temperatureCelsius",
                60.0
              ]
            },
            "then": 2,
            "else": {
              "if": {
                ">": [
                  "currentAmperes",
                  7.0
                ]
              },
              "then": 1,
              "else": 0
            }
          }
        }
      }
    ],
    "updates": [
      {
        "assign": "faultEntry",
        "value": {
          "and": [
            "io_2",
            {
              "not": "previousVibration"
            }
          ]
        }
      },
      {
        "assign": "displayPhaseMs",
        "value": "displayPhaseMs + io_7"
      },
      {
        "assign": "displayPhaseMs",
        "value": "displayPhaseMs - 6000.0 * RealFunctions::floor(displayPhaseMs / 6000.0)"
      },
      {
        "assign": "previousVibration",
        "value": "io_2"
      }
    ],
    "outputs": {
      "io_3": {
        "if": {
          ">": [
            "temperatureCelsius",
            60.0
          ]
        },
        "then": 255.0,
        "else": 0.0
      },
      "io_4": {
        "if": "io_2",
        "then": 2000,
        "else": 0
      },
      "io_5": "io_2",
      "io_6": {
        "if": {
          "<": [
            "displayPhaseMs",
            2000.0
          ]
        },
        "then": {
          "floor": "currentAmperes"
        },
        "else": {
          "if": {
            "<": [
              "displayPhaseMs",
              4000.0
            ]
          },
          "then": {
            "floor": "temperatureCelsius"
          },
          "else": "motorStatus"
        }
      },
      "serial_0_trigger": "faultEntry",
      "serial_0_value_0": {
        "if": "io_2",
        "then": 3,
        "else": 0
      }
    }
  },
  "req_test_map": {
    "requirements_to_testpoints": [
      {
        "requirement_id": "R1",
        "test_point_id": "T1",
        "test_method": "trace",
        "stimulus": "With io_2=false, test current below, at and above 7 A and temperature below, at and above 60 C using the disclosed inverse ADC calibrations. Observe status during the 4000–5999 ms display phase; also combine overload and overheat.",
        "oracle": "Status is 0 when neither strict threshold is exceeded, 1 for overload alone, and 2 whenever overheated without vibration. Fan io_3 is 255.0 only above 60 C and otherwise 0.0. Each sampled input change affects the applicable output on the next control step."
      },
      {
        "requirement_id": "R1",
        "test_point_id": "T2",
        "test_method": "trace",
        "stimulus": "Assert io_2 during normal, overloaded and overheated conditions; hold it true, clear it, and assert it again. Separately start with io_2=true on the first step.",
        "oracle": "Active vibration selects status 3, commands a continuous 2000 Hz alarm and LED ON, and emits exactly one 'Fault code: 3' line on each entry, including startup entry. Holding vibration does not repeat the report. Clearing vibration silences the alarm and turns the LED OFF. Fan control remains determined independently by temperature."
      },
      {
        "requirement_id": "R1",
        "test_point_id": "T3",
        "test_method": "trace",
        "stimulus": "Start with io_7=0 and advance actual elapsed deltas through 2000, 4000, 6000 and subsequent cycle boundaries. Include irregular deltas and a delta spanning multiple display slots.",
        "oracle": "Display io_6 shows floored calibrated current during phase [0,2000), floored calibrated Celsius during [2000,4000), and status during [4000,6000), repeating indefinitely. Boundary crossings preserve residual elapsed time, including skipped slots."
      },
      {
        "requirement_id": "R1",
        "test_point_id": "T4",
        "test_method": "trace",
        "stimulus": "Within each display slot, vary its selected quantity without advancing into another slot. Include ADC endpoints 0 and 1023, fractional calibrated readings, and all-zero initial inputs.",
        "oracle": "Selected values refresh on the next control step using floor rounding. ADC endpoints map to 0 and 10 amperes, and 0 and 500 Celsius. Initial zero inputs produce display 0, fan 0.0, tone 0, LED false and no serial report. No startup delay or blocking display wait is introduced."
      }
    ]
  }
}

